export function createSupportUI({e,actor,toast}){
 let data,view='board',search='',owner='',category='',token=0;
 const labels={done:'No Task',todo:'To Do',progress:'In Progress'},cats=['Hardware','Network','Classroom AV','Printing','Accounts','Software','Maintenance','Other'],today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tashkent'}),stamp=s=>new Date(s).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'});
 const opts=(values,v)=>values.map(x=>{const [id,name]=Array.isArray(x)?x:[x,x];return '<option value="'+e(id)+'" '+(v===id?'selected':'')+'>'+e(name)+'</option>';}).join('');
 async function api(path,body){const r=await fetch('/api/support/'+path,{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error||'Support could not be loaded.');return d;}
 function page(){const n=++token;queueMicrotask(async()=>{try{const d=await api('board');if(n!==token||!document.querySelector('#support-root'))return;data=d;paint();}catch(err){if(n===token&&document.querySelector('#support-root'))document.querySelector('#support-root').textContent=err.message;}});return '<section class="vle"><div class="learning-section-title"><h1>Technical support</h1><span>One request. Everything the team needs.</span></div><div id="support-root">Opening the support desk…</div></section>';}
 const name=id=>data.technicians.find(t=>t.id===id)?.name||'Unassigned';
 function filtered(){return data.tasks.filter(t=>(!search||[t.number,t.title,t.location,t.description,t.asset,t.requesterName].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!category||t.category===category)&&(!owner||(owner==='mine'?t.assignee===actor().id:owner==='requested'?t.requesterId===actor().id:!t.assignee))).sort((a,b)=>((a.due||'9999').localeCompare(b.due||'9999'))||b.createdAt.localeCompare(a.createdAt));}
 function card(t){return '<button class="support-card" draggable="'+data.manager+'" data-ticket="'+e(t.id)+'"><small>#IT-'+t.number+' · '+e(t.category)+' <b class="support-priority">'+e(t.priority)+'</b></small><h3>'+e(t.title)+'</h3><p>'+e(t.location)+(t.asset?' · '+e(t.asset):'')+'</p><p>'+e(name(t.assignee))+'</p><footer><span class="'+(t.due<today()&&t.status!=='done'?'error':'')+'">'+(t.due?'Due '+e(t.due):'No due date')+'</span><span>'+t.checklist.filter(x=>x.done).length+'/'+t.checklist.length+' ✓ · '+t.comments.length+' comments · '+t.attachments.length+' files</span></footer></button>';}
 function paint(){const root=document.querySelector('#support-root');if(!root)return;const rows=filtered();root.innerHTML='<div class="support-toolbar"><div class="actions">'+['board','list','calendar','charts','log'].map(v=>'<button class="btn '+(view===v?'primary':'')+'" data-support-view="'+v+'">'+({board:'Board',list:'Grid',calendar:'Calendar',charts:'Charts',log:'Activity log'}[v])+'</button>').join('')+'</div><button class="btn primary" data-support-new>+ New support request</button></div><div class="support-toolbar"><label>Search<input data-support-search value="'+e(search)+'" placeholder="Task, room, asset or requester"></label><label>Show<select data-support-owner>'+opts([['','All visible requests'],['requested','Requested by me'],...(data.manager?[['mine','Assigned to me']]:[]),['unassigned','Unassigned']],owner)+'</select></label><label>Category<select data-support-category>'+opts([['','All categories'],...cats],category)+'</select></label><button class="btn" data-support-refresh>Refresh</button><button class="btn" data-support-export>Export log CSV</button><span>'+rows.length+' requests</span></div>'+(data.manager?'':'<p class="vle-note">Your requests and their updates are shown here. Technicians see the central school board.</p>')+content(rows)+'<p class="muted"><small>Fictional demo · Changes stay in this browser. Switch accounts here to test the complete request workflow.</small></p>';bind(root);}
 function content(rows){if(view==='board')return '<div class="support-board">'+['done','todo','progress'].map(s=>'<section class="support-column" data-support-drop="'+s+'"><h2>'+labels[s]+' <span>'+rows.filter(t=>t.status===s).length+'</span></h2><p>'+(s==='done'?'Completed work · retained for tracking':s==='todo'?'Submitted requests awaiting action':'Assigned work being handled')+'</p><div class="support-cards">'+rows.filter(t=>t.status===s).map(card).join('')+'</div></section>').join('')+'</div>';
 if(view==='log'){const ids=new Set(rows.map(t=>t.id));return '<div class="table-wrap support-scroll"><table class="data-table"><thead><tr><th>When</th><th>Task</th><th>By</th><th>Activity</th></tr></thead><tbody>'+data.activity.filter(a=>ids.has(a.taskId)).slice().reverse().map(a=>'<tr><td>'+e(stamp(a.at))+'</td><td><button class="text-button" data-ticket="'+e(a.taskId)+'">IT-'+a.number+'</button></td><td>'+e(a.actorName)+'</td><td>'+e(a.action)+'<small> '+e(a.fields.join(', '))+'</small></td></tr>').join('')+'</tbody></table></div>';}
 if(view==='charts')return '<div class="support-board">'+['done','todo','progress'].map(s=>'<section class="vle-panel"><h2>'+labels[s]+'</h2><strong class="support-total">'+rows.filter(t=>t.status===s).length+'</strong></section>').join('')+'</div><section class="vle-panel"><h2>Open workload</h2>'+data.technicians.map(t=>{const n=rows.filter(r=>r.assignee===t.id&&r.status!=='done').length;return '<p>'+e(t.name)+' · '+n+' <meter min="0" max="'+Math.max(1,rows.length)+'" value="'+n+'">'+n+'</meter></p>';}).join('')+'<p>Overdue: '+rows.filter(t=>t.due&&t.due<today()&&t.status!=='done').length+' · Unassigned: '+rows.filter(t=>!t.assignee&&t.status!=='done').length+'</p></section>';
 if(view==='calendar')return '<div class="support-calendar support-scroll">'+[...new Set(rows.map(t=>t.due||'No due date'))].sort().map(day=>'<section class="vle-panel"><h2>'+e(day)+'</h2>'+rows.filter(t=>(t.due||'No due date')===day).map(card).join('')+'</section>').join('')+'</div>';
 return '<div class="table-wrap support-scroll"><table class="data-table"><thead><tr><th>Request</th><th>Location</th><th>Requester</th><th>Assigned to</th><th>Due</th><th>Priority</th><th>Status</th></tr></thead><tbody>'+rows.map(t=>'<tr><td><button class="text-button" data-ticket="'+e(t.id)+'">IT-'+t.number+' · '+e(t.title)+'</button></td><td>'+e(t.location)+'</td><td>'+e(t.requesterName)+'</td><td>'+e(name(t.assignee))+'</td><td>'+e(t.due)+'</td><td>'+e(t.priority)+'</td><td>'+labels[t.status]+'</td></tr>').join('')+'</tbody></table></div>';}
 async function refresh(){data=await api('board');paint();}
 function bind(root){root.querySelectorAll('[data-support-view]').forEach(b=>b.onclick=()=>{view=b.dataset.supportView;paint();});root.querySelector('[data-support-new]').onclick=()=>edit();for(const [selector,key]of [['[data-support-owner]','owner'],['[data-support-category]','category']])root.querySelector(selector).onchange=ev=>{if(key==='owner')owner=ev.target.value;else category=ev.target.value;paint();};root.querySelector('[data-support-search]').onchange=ev=>{search=ev.target.value;paint();};root.querySelector('[data-support-refresh]').onclick=()=>refresh().catch(err=>toast(err.message));root.querySelectorAll('[data-ticket]').forEach(b=>{b.onclick=()=>edit(data.tasks.find(t=>t.id===b.dataset.ticket));b.ondragstart=ev=>{if(data.manager)ev.dataTransfer.setData('text/plain',b.dataset.ticket);};});if(data.manager)root.querySelectorAll('[data-support-drop]').forEach(col=>{col.ondragover=ev=>ev.preventDefault();col.ondrop=ev=>{ev.preventDefault();const t=data.tasks.find(t=>t.id===ev.dataTransfer.getData('text/plain'));if(t)edit({...t},col.dataset.supportDrop);};});root.querySelector('[data-support-export]').onclick=()=>{const ids=new Set(filtered().map(t=>t.id)),lines=[['Time','Task','Actor','Action','Fields'],...data.activity.filter(a=>ids.has(a.taskId)).map(a=>[a.at,'IT-'+a.number,a.actorName,a.action,a.fields.join('; ')])];download('technical-support-activity.csv','text/csv',lines.map(r=>r.map(v=>'"'+String(/^[=+@-]/.test(String(v))?"'"+v:v).replaceAll('"','""')+'"').join(',')).join('\r\n'));};}
 function download(filename,type,value){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
 function edit(task=null,status){const t=task||{title:'',location:'',description:'',start:'',due:today(),priority:'Normal',category:'Hardware',asset:'',assignee:'',status:'todo',resolution:'',checklist:[],attachments:[],comments:[]},editable=!task||data.manager||t.status==='todo';let files=[...t.attachments];const dialog=document.createElement('dialog');dialog.className='support-dialog';dialog.innerHTML='<form class="support-form"><div class="learning-section-title"><h2>'+(task?'IT-'+t.number+' · Task details':'New support request')+'</h2><button type="button" class="btn" data-support-close>Close</button></div>'+(task?'<p>Requested by '+e(t.requesterName)+' · '+e(stamp(t.createdAt))+'</p>':'')+'<fieldset '+(!editable?'disabled':'')+'><div class="form-grid">'+field('Task name','title',t.title,'text',true)+field('Room / location','location',t.location,'text',true)+field('Start date','start',t.start,'date')+field('Due date','due',t.due,'date')+'<label class="field"><span>Assign technician</span><select name="assignee">'+opts([['','Unassigned — team triage'],...data.technicians.map(x=>[x.id,x.name])],t.assignee)+'</select></label><label class="field"><span>Priority</span><select name="priority">'+opts(['Low','Normal','High','Urgent'],t.priority)+'</select></label><label class="field"><span>Category</span><select name="category">'+opts(cats,t.category)+'</select></label>'+field('Asset / device reference','asset',t.asset)+'<label class="field full"><span>Issue details</span><textarea name="description" rows="4" required maxlength="8000">'+e(t.description)+'</textarea></label><label class="field full"><span>Checklist · one step per line</span><textarea name="steps" rows="2">'+e(t.checklist.map(x=>x.text).join('\n'))+'</textarea></label>'+(data.manager?'<label class="field"><span>Status / bucket</span><select name="status">'+opts(Object.entries(labels),status||t.status)+'</select></label><label class="field"><span>Completion notes</span><textarea name="resolution" rows="2">'+e(t.resolution)+'</textarea></label>':'')+'<label class="field full"><span>Attachments · up to 3 files, 1 MB each</span><input type="file" multiple name="uploads"></label></div></fieldset><div class="full" data-support-files></div>'+(data.manager&&t.checklist.length?'<div data-support-checks>'+t.checklist.map((x,i)=>'<label><input type="checkbox" data-check="'+i+'" '+(x.done?'checked':'')+'> '+e(x.text)+'</label>').join('')+'</div>':'')+'<p class="error" role="alert" data-support-error></p>'+(editable?'<button class="btn primary" type="submit">'+(task?'Save task':'Submit to To Do')+'</button>':'<p>The team is handling this request. You can add a comment below.</p>')+'</form>'+(task?'<section class="support-comments"><h3>Comments & updates</h3>'+t.comments.map(c=>'<p><strong>'+e(c.author)+'</strong> · '+e(stamp(c.at))+'<br>'+e(c.message)+'</p>').join('')+'<form data-support-comment><label class="field"><span>Add a comment</span><textarea name="message" required maxlength="3000" rows="2"></textarea></label><button class="btn">Post comment</button></form><details><summary>Task activity</summary>'+data.activity.filter(a=>a.taskId===t.id).slice().reverse().map(a=>'<p>'+e(stamp(a.at))+' · '+e(a.actorName)+' · '+e(a.action)+' '+e(a.fields.join(', '))+'</p>').join('')+'</details></section>':'');document.body.append(dialog);dialog.showModal();const close=()=>{dialog.close();dialog.remove();};dialog.querySelector('[data-support-close]').onclick=close;dialog.addEventListener('close',()=>dialog.remove());
 function fileList(){dialog.querySelector('[data-support-files]').innerHTML=files.map((f,i)=>'<span><button type="button" class="text-button" data-file="'+i+'">'+e(f.name)+'</button> '+(editable?'<button type="button" class="text-button" data-remove-file="'+i+'" aria-label="Remove '+e(f.name)+'">×</button>':'')+'</span>').join(' · ');dialog.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{const f=files[Number(b.dataset.file)],a=document.createElement('a');a.href=f.data;a.download=f.name;a.click();});dialog.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{files.splice(Number(b.dataset.removeFile),1);fileList();});}fileList();
 const form=dialog.querySelector('.support-form'),error=dialog.querySelector('[data-support-error]');let uploading=false;form.elements.uploads.onchange=async ev=>{uploading=true;try{const selected=[...ev.target.files];if(files.length+selected.length>3||selected.some(f=>f.size>1024*1024))throw Error('Choose up to three files, at most 1 MB each.');const added=await Promise.all(selected.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:'data:application/octet-stream;base64,'+String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('Could not read the file.'));reader.readAsDataURL(f);})));files.push(...added);fileList();error.textContent='';}catch(err){error.textContent=err.message;}finally{uploading=false;ev.target.value='';}};
 form.onsubmit=async ev=>{ev.preventDefault();if(uploading){error.textContent='Wait for attachments to finish loading.';return;}const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const d=Object.fromEntries(new FormData(form));const checklist=d.steps.split('\n').filter(x=>x.trim()).map((text,i)=>({text,done:!!dialog.querySelector('[data-check="'+i+'"]')?.checked}));await api('save',{...d,id:task?.id,expectedRevision:task?.revision,checklist,attachments:files,status:d.status||t.status,resolution:d.resolution||t.resolution});close();await refresh();toast(task?'Support task saved.':'Request submitted to the support team.');}catch(err){error.textContent=err.message;submit.disabled=false;}};
 dialog.querySelector('[data-support-comment]')?.addEventListener('submit',async ev=>{ev.preventDefault();const b=ev.currentTarget.querySelector('button');b.disabled=true;try{await api('comment',{id:t.id,message:ev.currentTarget.elements.message.value});close();await refresh();edit(data.tasks.find(x=>x.id===t.id));}catch(err){error.textContent=err.message;b.disabled=false;}});
 }
 function field(label,name,value,type='text',required=false){return '<label class="field"><span>'+label+'</span><input name="'+name+'" type="'+type+'" value="'+e(value)+'" '+(required?'required':'')+' maxlength="160"></label>';}
 return{page};
}
